FILES = {'scripts/train_model16.py': '"""Fine-tune the last CoAtNet stage on verified dense pixels and v4 weak targets."""\nimport argparse\nimport copy\nimport hashlib\nimport json\nfrom pathlib import Path\nimport random\nimport sys\nimport time\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT))\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom torch.utils.data import Dataset, DataLoader\nfrom sklearn.metrics import roc_auc_score\nfrom knee.dense import DenseCache\nfrom cloud.prepare_dense_cache import EXPECTED_GEOMETRY\nfrom model12.inference import Classifier, LABELS, UID, windows\n\n\nclass Studies(Dataset):\n    def __init__(self, cache, ids, targets, n_windows=None):\n        self.cache = DenseCache(cache, ids)\n        self.targets = targets.loc[ids, LABELS].to_numpy(dtype=np.float32)\n        self.n_windows = n_windows\n\n    def __len__(self):\n        return len(self.cache)\n\n    def __getitem__(self, i):\n        volume, mask = self.cache[i]\n        images = windows(volume, mask, 384)\n        if self.n_windows is not None:\n            n = len(images)\n            idx = torch.randperm(n)\n            idx = idx.repeat((self.n_windows+n-1)//n)[:self.n_windows]\n            images = images[idx]\n        return images, torch.from_numpy(self.targets[i])\n\n\ndef forward(model, images):\n    b, k = images.shape[:2]\n    encoded = torch.cat([model.backbone(chunk) for chunk in images.flatten(0, 1).split(12)])\n    return model.predict_features(encoded.reshape(b, k, -1))\n\n\n@torch.inference_mode()\ndef evaluate(model, dataset, device):\n    model.eval()\n    numerator = denominator = 0.0\n    predictions = []\n    for images, target in DataLoader(dataset, batch_size=1, num_workers=0):\n        images, target = images.to(device), target.to(device)\n        with torch.autocast(\'cuda\', dtype=torch.float16):\n            logits = forward(model, images)\n        probability = logits.float().sigmoid()\n        assert torch.isfinite(probability).all()\n        confidence = 2*(target-.5).abs()\n        numerator += float((F.binary_cross_entropy_with_logits(logits.float(), target, reduction=\'none\')*confidence).sum())\n        denominator += float(confidence.sum())\n        predictions.append(probability.cpu().numpy()[0])\n    assert denominator > 0\n    return numerator/denominator, np.asarray(predictions)\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--cache\', required=True)\n    parser.add_argument(\'--checkpoint\', required=True)\n    parser.add_argument(\'--output\', default=\'artifacts/model16\')\n    parser.add_argument(\'--smoke\', action=\'store_true\')\n    args = parser.parse_args()\n    config = json.loads((ROOT/\'model16/config.json\').read_text())\n    random.seed(config[\'seed\']); np.random.seed(config[\'seed\']); torch.manual_seed(config[\'seed\'])\n    assert torch.cuda.is_available(), \'Run GPU training on the authorized rental\'\n    device = torch.device(\'cuda\')\n    torch.set_num_threads(4)\n    cache = DenseCache(args.cache)\n    assert args.smoke or not cache.verified[\'pilot\']\n    assert cache.verified[\'geometry\'] == EXPECTED_GEOMETRY\n    assert cache.verified[\'source_metadata_sha256\'] == hashlib.sha256((ROOT/\'data/train.csv\').read_bytes()).hexdigest()\n    partition = pd.read_csv(ROOT/\'artifacts/partitions/partitions.csv\').set_index(UID)\n    targets = pd.read_csv(ROOT/config[\'targets\']).set_index(UID)\n    gold = pd.read_csv(ROOT/\'data/train.csv\').set_index(UID)\n    assert partition.index.is_unique and targets.index.is_unique\n    assert set(partition.index) == set(targets.index) == set(gold.index)\n    assert np.isfinite(targets[LABELS]).all().all()\n    assert ((targets[LABELS]>=0)&(targets[LABELS]<=1)).all().all()\n    train_ids = partition.index[partition.split==\'train\'].tolist()\n    val_ids = partition.index[partition.split==\'weak_val\'].tolist()\n    gold_ids = partition.index[partition.split==\'gold\'].tolist()\n    assert len(gold_ids)==58 and gold.loc[gold_ids,LABELS].notna().all().all()\n    assert set(partition.loc[train_ids,\'report_hash\']).isdisjoint(partition.loc[val_ids+gold_ids,\'report_hash\'])\n    if args.smoke:\n        train_ids = [uid for uid in train_ids if uid in cache.index.index][:2]\n        assert train_ids\n    else:\n        assert set(cache.index.index) == set(partition.index)\n    train_set = Studies(args.cache, train_ids, targets, config[\'train_windows\'])\n    ck = torch.load(args.checkpoint, map_location=\'cpu\', weights_only=True)\n    assert list(ck.get(\'lab\', LABELS)) == LABELS and int(ck[\'res\']) == 384\n    arch = ck[\'arch\']; student = Classifier(arch)\n    student.load_state_dict(ck[\'model\'], strict=True); del ck\n    teacher = copy.deepcopy(student).to(device).eval().requires_grad_(False)\n    student = student.to(device)\n    student.backbone.requires_grad_(False)\n    student.backbone.stages[-1].requires_grad_(True)\n    encoder = [p for p in student.backbone.parameters() if p.requires_grad]\n    head = [p for name,p in student.named_parameters() if not name.startswith(\'backbone.\')]\n    assert encoder and all(p.requires_grad for p in head)\n    optimizer = torch.optim.AdamW([{\'params\':encoder,\'lr\':config[\'encoder_lr\']},\n                                  {\'params\':head,\'lr\':config[\'head_lr\']}], weight_decay=config[\'weight_decay\'])\n    scaler = torch.amp.GradScaler(\'cuda\')\n    out = Path(args.output); out.mkdir(parents=True,exist_ok=True)\n    with Path(args.checkpoint).open(\'rb\') as stream:\n        checkpoint_hash = hashlib.file_digest(stream,\'sha256\').hexdigest()\n    provenance = {\'initial_checkpoint_sha256\':checkpoint_hash,\n                  \'targets_sha256\':hashlib.sha256((ROOT/config[\'targets\']).read_bytes()).hexdigest(),\n                  \'partition_sha256\':hashlib.sha256((ROOT/\'artifacts/partitions/partitions.csv\').read_bytes()).hexdigest(),\n                  \'config\':config,\'cache\':cache.verified,\'smoke\':args.smoke}\n    (out/\'provenance.json\').write_text(json.dumps(provenance,indent=2))\n    started = time.time(); history = []\n\n    def save(epoch, loss):\n        state = {\'model\':{k:v.detach().cpu() for k,v in student.state_dict().items()},\n                 \'arch\':arch,\'res\':384,\'lab\':LABELS,\'epoch\':epoch,\'weak_val_bce\':loss,\n                 \'training_config\':config}\n        torch.save(state, out/\'best.tmp\'); (out/\'best.tmp\').replace(out/\'best.pt\')\n\n    if not args.smoke:\n        validation = Studies(args.cache,val_ids,targets)\n        gold_set = Studies(args.cache,gold_ids,gold)\n        baseline_loss, _ = evaluate(student, validation, device)\n        _, baseline_gold = evaluate(student, gold_set, device)\n        best = baseline_loss; save(0,best)\n        history.append({\'epoch\':0,\'weak_val_bce\':best,\'gold_auc\':float(roc_auc_score(gold.loc[gold_ids,LABELS],baseline_gold))})\n        print(json.dumps(history[-1]),flush=True)\n    loader = DataLoader(train_set,batch_size=config[\'batch_size\'],shuffle=True,\n                        num_workers=0 if args.smoke else config[\'workers\'],pin_memory=True)\n    for epoch in range(1, (1 if args.smoke else config[\'epochs\'])+1):\n        student.eval(); student.backbone.stages[-1].train(); student.att.train()\n        for step,(images,target) in enumerate(loader):\n            images,target = images.to(device),target.to(device)\n            confidence = 2*(target-.5).abs()\n            optimizer.zero_grad(set_to_none=True)\n            with torch.autocast(\'cuda\',dtype=torch.float16):\n                with torch.no_grad(): teacher_prob = forward(teacher, images).float().sigmoid()\n                logits = forward(student,images).float()\n                supervised = (F.binary_cross_entropy_with_logits(logits,target,reduction=\'none\')*confidence).sum()/confidence.sum().clamp(min=1)\n                retention = F.binary_cross_entropy_with_logits(logits,teacher_prob)\n                loss = supervised + config[\'teacher_weight\']*retention\n            assert torch.isfinite(loss)\n            scaler.scale(loss).backward(); scaler.unscale_(optimizer)\n            norm = nn.utils.clip_grad_norm_(encoder+head,config[\'gradient_clip\'],error_if_nonfinite=True)\n            assert all(p.grad is None for p in teacher.parameters())\n            scaler.step(optimizer); scaler.update()\n            if step % 100 == 0: print(json.dumps({\'epoch\':epoch,\'step\':step,\'loss\':float(loss.detach()),\'gradient_norm\':float(norm)}),flush=True)\n            if args.smoke:\n                (out/\'SMOKE_PASS.json\').write_text(json.dumps({\'loss\':float(loss.detach()),\'weak_training_cases\':train_ids,\'trainable_parameters\':sum(p.numel() for p in encoder+head)}))\n                return\n        val_loss,_ = evaluate(student,validation,device)\n        history.append({\'epoch\':epoch,\'weak_val_bce\':val_loss})\n        if val_loss < best: best=val_loss;save(epoch,best)\n        (out/\'history.json\').write_text(json.dumps(history,indent=2));print(json.dumps(history[-1]),flush=True)\n    ck = torch.load(out/\'best.pt\',map_location=\'cpu\',weights_only=True)\n    student.load_state_dict(ck[\'model\'],strict=True)\n    _, pred = evaluate(student,gold_set,device)\n    pd.DataFrame(pred,index=pd.Index(gold_ids,name=UID),columns=LABELS).to_csv(out/\'gold_predictions.csv\')\n    metrics={\'selected_epoch\':ck[\'epoch\'],\'weak_val_bce\':best,\'gold_auc\':float(roc_auc_score(gold.loc[gold_ids,LABELS],pred)),\n             \'elapsed_seconds\':time.time()-started,\'notes\':\'Gold is descriptive development evidence; epoch chosen by weak BCE including baseline.\'}\n    (out/\'metrics.json\').write_text(json.dumps(metrics,indent=2));print(json.dumps(metrics),flush=True)\n    (out/\'TRAINING_COMPLETE\').write_text(\'Model16 complete; artifacts ready for backup.\\n\')\n\n\nif __name__==\'__main__\': main()\n', 'cloud/prepare_dense_cache.py': '"""Verify generated shards and unpack them for efficient random-access training."""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nEXPECTED_GEOMETRY = {\n    \'slots\': [[\'Sagittal\', 1, 18], [\'Sagittal\', 0, 14], [\'Coronal\', 1, 12],\n              [\'Coronal\', 0, 8], [\'Axial\', -1, 12]],\n    \'span\': [.02, .98], \'crop_mm\': 140, \'size\': 336,\n}\n\n\ndef prepare(manifests, train_path, destination, pilot=False):\n    destination = Path(destination)\n    destination.mkdir(parents=True, exist_ok=True)\n    # An interrupted rebuild must never retain an old ready marker.\n    (destination / \'verified.json\').unlink(missing_ok=True)\n    train = pd.read_csv(train_path)\n    assert train.StudyInstanceUID.is_unique and len(train) == 4407\n    expected_ids = set(train.StudyInstanceUID)\n    metadata_hash = hashlib.sha256(Path(train_path).read_bytes()).hexdigest()\n    rows, seen, parts, shard_names = [], set(), set(), set()\n    for manifest_path in map(Path, manifests):\n        manifest = json.loads(manifest_path.read_text())\n        assert manifest[\'geometry\'] == EXPECTED_GEOMETRY\n        assert manifest[\'kind\'] == (\'pilot\' if pilot else \'full_part\')\n        if not pilot:\n            assert manifest[\'parts\'] == 4 and manifest[\'part\'] not in parts\n            assert manifest[\'training_metadata_sha256\'] == metadata_hash\n            parts.add(manifest[\'part\'])\n        manifest_count = 0\n        for shard in manifest[\'shards\']:\n            filename = shard[\'file\']\n            assert Path(filename).name == filename and filename.endswith(\'.npz\')\n            assert filename not in shard_names\n            shard_names.add(filename)\n            path = manifest_path.parent / filename\n            assert path.stat().st_size == shard[\'bytes\']\n            with path.open(\'rb\') as stream:\n                assert hashlib.file_digest(stream, \'sha256\').hexdigest() == shard[\'sha256\']\n            with np.load(path, allow_pickle=False) as archive:\n                ids = archive[\'ids\'].tolist()\n                volumes, masks = archive[\'volumes\'], archive[\'masks\']\n            assert ids == shard[\'ids\'] and len(set(ids)) == len(ids)\n            assert not seen.intersection(ids) and set(ids).issubset(expected_ids)\n            assert volumes.dtype == np.uint8 and volumes.shape == (len(ids), 64, 336, 336)\n            assert masks.shape == (len(ids), 64)\n            assert np.array_equal(masks, volumes.reshape(len(ids), 64, -1).sum(2) > 0)\n            assert masks.any(axis=1).all()\n            basename = Path(filename).stem\n            for suffix, array in [(\'volumes\', volumes), (\'masks\', masks.astype(bool))]:\n                target = destination / f\'{basename}_{suffix}.npy\'\n                temporary = target.with_suffix(\'.tmp\')\n                with temporary.open(\'wb\') as stream:\n                    np.save(stream, array, allow_pickle=False)\n                temporary.replace(target)\n            for i, uid in enumerate(ids):\n                rows.append({\'StudyInstanceUID\': uid, \'volume_file\': f\'{basename}_volumes.npy\',\n                             \'mask_file\': f\'{basename}_masks.npy\', \'row\': i})\n            seen.update(ids)\n            manifest_count += len(ids)\n            print(\'Verified/unpacked\', filename, \'studies\', len(ids), flush=True)\n        assert manifest_count == manifest[\'studies\']\n    if pilot:\n        assert len(seen) == 64\n    else:\n        assert parts == {0, 1, 2, 3} and seen == expected_ids\n    index = pd.DataFrame(rows).set_index(\'StudyInstanceUID\')\n    order = [uid for uid in train.StudyInstanceUID if uid in seen]\n    index = index.loc[order].reset_index()\n    index.to_csv(destination / \'index.csv\', index=False)\n    summary = {\'studies\': len(index), \'pilot\': pilot, \'geometry\': EXPECTED_GEOMETRY,\n               \'source_metadata_sha256\': metadata_hash, \'verified_shards\': len(shard_names)}\n    (destination / \'verified.json\').write_text(json.dumps(summary, indent=2))\n    return summary\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\'--manifest\', nargs=\'+\', required=True)\n    parser.add_argument(\'--train\', default=\'data/train.csv\')\n    parser.add_argument(\'--destination\', required=True)\n    parser.add_argument(\'--pilot\', action=\'store_true\')\n    args = parser.parse_args()\n    print(prepare(args.manifest, args.train, args.destination, args.pilot))\n', 'knee/dense.py': '"""Memory-mapped access to the verified model12-compatible dense MRI cache."""\nfrom collections import OrderedDict\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\nclass DenseCache:\n    def __init__(self, root, ids=None, max_open_shards=8):\n        self.root = Path(root)\n        self.verified = json.loads((self.root / \'verified.json\').read_text())\n        frame = pd.read_csv(self.root / \'index.csv\').set_index(\'StudyInstanceUID\')\n        assert frame.index.is_unique and len(frame) == self.verified[\'studies\']\n        self.index = frame if ids is None else frame.loc[list(ids)]\n        self.open_arrays = OrderedDict()\n        self.max_open_shards = max_open_shards\n        assert max_open_shards >= 1\n\n    def __len__(self):\n        return len(self.index)\n\n    def _open(self, filename):\n        assert Path(filename).name == filename\n        if filename in self.open_arrays:\n            array = self.open_arrays.pop(filename)\n        else:\n            array = np.load(self.root / filename, mmap_mode=\'r\', allow_pickle=False)\n        self.open_arrays[filename] = array\n        while len(self.open_arrays) > self.max_open_shards * 2:\n            self.open_arrays.popitem(last=False)\n        return array\n\n    def __getitem__(self, i):\n        row = self.index.iloc[i]\n        volume = np.array(self._open(row.volume_file)[int(row.row)], copy=True)\n        mask = np.array(self._open(row.mask_file)[int(row.row)], dtype=bool, copy=True)\n        assert volume.shape == (64, 336, 336) and volume.dtype == np.uint8\n        assert mask.shape == (64,) and mask.any()\n        return volume, mask\n', 'knee/data.py': "import hashlib\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.model_selection import GroupShuffleSplit\n\nUID = 'StudyInstanceUID'\n\n\ndef report_hash(value):\n    return hashlib.sha256(' '.join(str(value).lower().split()).encode()).hexdigest()\n\n\ndef make_partitions(data_dir, out_dir):\n    data_dir, out_dir = Path(data_dir), Path(out_dir)\n    train = pd.read_csv(data_dir / 'train.csv')\n    labels = list(pd.read_csv(data_dir / 'sample_submission.csv').columns.drop(UID))\n    weak = pd.read_csv(data_dir / 'weak_labels/llm_labels_full.csv')\n    assert train[UID].is_unique and weak[UID].is_unique\n    assert set(train[UID]) == set(weak[UID]), 'Weak target UID mismatch'\n    probs = weak.set_index(UID).loc[train[UID], labels].to_numpy(dtype=np.float32)\n    assert np.isfinite(probs).all() and ((probs >= 0) & (probs <= 1)).all()\n    groups = train.Report.map(report_hash)\n    gold_mask = train[labels].notna().all(axis=1).to_numpy()\n    excluded_groups = set(groups[gold_mask])\n    eligible = np.flatnonzero(~gold_mask & ~groups.isin(excluded_groups).to_numpy())\n    a, b = next(GroupShuffleSplit(n_splits=1, test_size=0.15, random_state=2026)\n                .split(eligible, groups=groups.iloc[eligible]))\n    split = np.full(len(train), 'excluded', dtype=object)\n    split[eligible[a]] = 'train'\n    split[eligible[b]] = 'weak_val'\n    split[gold_mask] = 'gold'\n    assert set(groups[split == 'train']).isdisjoint(groups[split == 'weak_val'])\n    assert set(groups[split == 'train']).isdisjoint(groups[split == 'gold'])\n    manifest = train[[UID]].assign(split=split, report_hash=groups)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    manifest.to_csv(out_dir / 'partitions.csv', index=False)\n    np.savez(out_dir / 'targets.npz', weak=probs,\n             gold=train[labels].to_numpy(dtype=np.float32),\n             confidence=2 * np.abs(probs - 0.5))\n    (out_dir / 'labels.json').write_text(json.dumps(labels))\n    return manifest\n\n\nclass PixelCache:\n    def __init__(self, root, ids=None):\n        self.root = Path(root)\n        index = pd.read_csv(self.root / 'studies.csv')\n        if not index[UID].is_unique:\n            raise ValueError('Duplicate cache study ID')\n        index['mask_row'] = np.arange(len(index))\n        self.index = index if ids is None else index.set_index(UID).loc[list(ids)].reset_index()\n        self.mask = np.load(self.root / 'slot_mask.npy', allow_pickle=False)\n        self.shards = {}\n\n    def __len__(self):\n        return len(self.index)\n\n    def __getitem__(self, i):\n        row = self.index.iloc[i]\n        shard = str(row['shard'])\n        if shard not in self.shards:\n            self.shards[shard] = np.load(self.root / shard, mmap_mode='r', allow_pickle=False)\n        pixels = np.array(self.shards[shard][int(row['row'])], copy=True)\n        mask = np.asarray(self.mask[int(row['mask_row'])], dtype=bool)\n        if pixels.shape != (6, 9, 224, 224) or pixels.dtype != np.uint8:\n            raise ValueError(f'Unexpected pixel shape/dtype: {pixels.shape}, {pixels.dtype}')\n        if not mask.any():\n            raise ValueError('Study has no available MRI slots')\n        return pixels, mask\n", 'model12/inference.py': '"""CoAtNet inference compatible with Dread Development\'s public knee checkpoint.\n\nArchitecture and geometry credit: Johnathan Wagner / Dread Development.\nSource: https://www.kaggle.com/code/dreaddevelopment/knee-mri-twelve-findings-from-a-single-model\nModel12: max-span checkpoint with documented 2%-98% sampling.\nThis implementation uses only images and public series metadata.\n"""\nimport gc\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nos.environ[\'HF_HUB_OFFLINE\'] = \'1\'\nos.environ[\'TRANSFORMERS_OFFLINE\'] = \'1\'\n\nimport cv2\nimport numpy as np\nimport pandas as pd\nimport pydicom\nimport timm\nimport torch\nfrom pydicom.pixels import apply_modality_lut\nfrom torch import nn\nfrom torch.nn import functional as F\n\nUID = \'StudyInstanceUID\'\nSLOTS = [(\'Sagittal\', 1, 18), (\'Sagittal\', 0, 14), (\'Coronal\', 1, 12),\n         (\'Coronal\', 0, 8), (\'Axial\', -1, 12)]\nLABELS = [\'ACL\', \'MCL\', \'Medial Meniscus\', \'Lateral Meniscus\', \'Medial OA\',\n          \'Lateral OA\', \'PF OA\', \'Effusion\', \'Synovitis\', "Baker\'s", \'Contusion\', \'Fracture\']\n\n\nclass Classifier(nn.Module):\n    def __init__(self, arch):\n        super().__init__()\n        self.backbone = timm.create_model(arch, pretrained=False, num_classes=0,\n                                          in_chans=3, global_pool=\'avg\')\n        dim = self.backbone.num_features\n        self.norm = nn.LayerNorm(dim)\n        self.att = nn.Sequential(nn.Linear(dim, 256), nn.Tanh(), nn.Dropout(.2), nn.Linear(256, 12))\n        self.clsW = nn.Parameter(torch.zeros(12, dim))\n        self.clsb = nn.Parameter(torch.zeros(12))\n\n    def predict_features(self, features):\n        features = self.norm(features)\n        attention = self.att(features).softmax(dim=1)\n        pooled = torch.einsum(\'bkn,bkf->bnf\', attention, features)\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n\ndef ordered_files(directory):\n    records = []\n    for path in directory.glob(\'*.dcm\'):\n        header = pydicom.dcmread(path, stop_before_pixels=True)\n        orientation = getattr(header, \'ImageOrientationPatient\', None)\n        position = getattr(header, \'ImagePositionPatient\', None)\n        if orientation is not None and position is not None and len(orientation) == 6:\n            normal = np.cross(np.asarray(orientation[:3], float), np.asarray(orientation[3:], float))\n            order = float(np.dot(np.asarray(position, float), normal))\n        else:\n            order = float(getattr(header, \'InstanceNumber\', 0) or 0)\n        spacing = getattr(header, \'PixelSpacing\', None)\n        records.append((order, path, float(spacing[0]) if spacing is not None else .5))\n    records.sort(key=lambda x: x[0])\n    return records\n\n\ndef read_study(uid, rows, series_root):\n    volume = np.zeros((64, 336, 336), dtype=np.uint8)\n    used, offset, failed = set(), 0, 0\n    for plane, fluid, count in SLOTS:\n        candidates = [r for r in rows if r[\'Anatomical_Plane\'] == plane and r[\'SeriesInstanceUID\'] not in used]\n        preferred = [r for r in candidates if int(r[\'Fluid_Sensitive\']) == fluid] if fluid in (0,1) else []\n        chosen = (preferred or candidates)\n        if not chosen:\n            offset += count\n            continue\n        row = chosen[0]; used.add(row[\'SeriesInstanceUID\'])\n        records = ordered_files(series_root / uid / row[\'SeriesInstanceUID\'])\n        if not records:\n            raise FileNotFoundError(\'Declared series has no DICOM files\')\n        n = len(records); lo = int(n * .02); hi = max(lo, int(n * .98)-1)\n        indices = np.rint(np.linspace(lo, hi, count)).astype(int) if n > 1 else np.zeros(count, dtype=int)\n        selected = []\n        for i in indices:\n            _, path, spacing = records[min(i, n-1)]\n            try:\n                ds = pydicom.dcmread(path)\n                array = apply_modality_lut(ds.pixel_array, ds).astype(np.float32)\n                if array.ndim != 2 or not np.isfinite(array).all():\n                    raise ValueError(\'Invalid decoded MRI pixels\')\n                if str(getattr(ds, \'PhotometricInterpretation\', \'\')) == \'MONOCHROME1\':\n                    array = array.max() - array\n                selected.append((array, spacing))\n            except (ValueError, RuntimeError, NotImplementedError):\n                selected.append((None, spacing)); failed += 1\n        valid = [a for a, _ in selected if a is not None]\n        if not valid:\n            raise ValueError(\'No decodable slices in selected series\')\n        low, high = np.percentile(np.concatenate([a.ravel() for a in valid]), [2, 98])\n        median_spacing = float(np.median([r[2] for r in records]))\n        for array, spacing in selected:\n            if array is not None:\n                array = np.clip((array-low)/(high-low+1e-6), 0, 1)\n                spacing = spacing if spacing > 0 else median_spacing\n                h, w = array.shape\n                size = min(int(round(140/max(spacing, 1e-3))), h, w)\n                y, x = (h-size)//2, (w-size)//2\n                crop = cv2.resize(array[y:y+size, x:x+size], (336,336), interpolation=cv2.INTER_AREA)\n                volume[offset] = (crop * 255).astype(np.uint8)\n            offset += 1\n    mask = volume.reshape(64,-1).sum(1) > 0\n    if not mask.any():\n        raise ValueError(\'Study has no usable images\')\n    return volume, mask, failed\n\n\ndef windows(volume, mask, size):\n    valid = np.flatnonzero(mask)\n    if len(valid) < 3:\n        valid = np.arange(3)\n    lo, hi = int(valid.min()), int(valid.max())\n    centers = list(range(lo+1, hi)) or [max(1, min((lo+hi)//2, len(volume)-2))]\n    indices = np.arange(len(centers))\n    slices = np.stack([volume[centers[i]-1:centers[i]+2] for i in indices]).astype(np.float32) / 255\n    images = F.interpolate(torch.from_numpy(slices), size=(size,size), mode=\'bilinear\', align_corners=False)\n    return (images - torch.tensor([.485,.456,.406]).view(1,3,1,1)) / torch.tensor([.229,.224,.225]).view(1,3,1,1)\n\n\n@torch.inference_mode()\ndef predict(model, images, device):\n    encoded = []\n    with torch.autocast(device.type, enabled=device.type==\'cuda\', dtype=torch.float16):\n        for batch in images.split(12):\n            encoded.append(model.backbone(batch.to(device)))\n        logits = model.predict_features(torch.cat(encoded).unsqueeze(0))\n    probabilities = logits.float().sigmoid().cpu().numpy()[0]\n    if not np.isfinite(probabilities).all():\n        raise ValueError(\'Nonfinite model predictions\')\n    return probabilities\n\n\ndef main():\n    started = time.time();torch.set_num_threads(4)\n    torch.backends.cudnn.benchmark = True\n    device = torch.device(\'cuda\' if torch.cuda.is_available() else \'cpu\')\n    print(\'Device:\', device, \'torch:\', torch.__version__, \'timm:\', timm.__version__, flush=True)\n    if device.type == \'cuda\':print(\'GPU:\', torch.cuda.get_device_name(), flush=True)\n    inputs = Path(\'/kaggle/input\')\n    roots = [p for p in [inputs/\'competitions/rsna-knee-abnormality-detection\', inputs/\'rsna-knee-abnormality-detection\']\n             if (p/\'test.csv\').exists()]\n    assert len(roots)==1\n    root = roots[0]\n    filename = \'raptor_ft_coatnet_v5_full_swa.pt\'\n    candidates = [inputs/\'raptor-knee-maxspan\'/filename]\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-maxspan/\'+filename))\n    candidates += list(inputs.glob(\'datasets/dreaddevelopment/raptor-knee-maxspan/*/\'+filename))\n    files = [p for p in candidates if p.is_file()]\n    assert len(files)==1, files\n    ck = torch.load(files[0], map_location=\'cpu\', weights_only=True)\n    print(\'Checkpoint metadata:\', {k: v for k, v in ck.items() if isinstance(v, (str, int, float, bool))}, flush=True)\n    assert list(ck.get(\'lab\', LABELS)) == LABELS\n    model = Classifier(ck[\'arch\']);model.load_state_dict(ck[\'model\'], strict=True)\n    size = int(ck[\'res\']);del ck;gc.collect()\n    model = model.to(device).eval()\n    test = pd.read_csv(root/\'test.csv\');series = pd.read_csv(root/\'test_series.csv\')\n    sample = pd.read_csv(root/\'sample_submission.csv\')\n    assert test[UID].is_unique and sample[UID].is_unique\n    groups = {uid: frame.to_dict(\'records\') for uid,frame in series.groupby(UID)}\n    result = []\n    for i, uid in enumerate(test[UID]):\n        volume, mask, failed = read_study(uid, groups[uid], root/\'test_series\')\n        result.append(predict(model, windows(volume, mask, size), device))\n        if failed:print(json.dumps({\'study\':i,\'failed_slices\':failed}),flush=True)\n        if i % 50 == 0 or i+1 == len(test):print(\'Predicted\',i+1,\'/\',len(test),\'seconds\',round(time.time()-started,1),flush=True)\n    frame = pd.DataFrame(result, columns=LABELS);frame.insert(0,UID,test[UID].to_numpy())\n    submission = sample[[UID]].merge(frame,on=UID,validate=\'one_to_one\')[sample.columns]\n    assert len(submission)==len(test) and np.isfinite(submission[LABELS]).all().all()\n    submission.to_csv(\'/kaggle/working/submission.csv\',index=False)\n    print(\'Wrote submission.csv; seconds:\',round(time.time()-started,1),flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n', 'model16/config.json': '{\n  "seed": 20260911,\n  "epochs": 2,\n  "train_windows": 12,\n  "batch_size": 2,\n  "workers": 2,\n  "encoder_lr": 0.000005,\n  "head_lr": 0.00001,\n  "weight_decay": 0.01,\n  "teacher_weight": 0.3,\n  "gradient_clip": 1.0,\n  "targets": "data/weak_labels_v4/llm_labels_v4_blend.csv",\n  "selection": "confidence-weighted weak validation BCE, including epoch zero"\n}\n'}
