inputs=Path('/kaggle/input')
def locate(slug,owner,kind,filename):
    candidates=[inputs/slug,inputs/kind/owner/slug]
    matches=[p for p in candidates if (p/filename).exists()]
    assert len(matches)==1,(slug,matches)
    return matches[0]
